# Reverse the decode function
def encode_combination(target_bytes):
    """Reverse the decode function to find the input"""
    result = []
    for b in target_bytes:
        # decode does: ((ord(ch) ^ 0x42) + 1) & 0xFF = b
        # So: (ord(ch) ^ 0x42) + 1 = b (assuming no overflow)
        # Therefore: ord(ch) ^ 0x42 = b - 1
        # Therefore: ord(ch) = (b - 1) ^ 0x42
        original = ((b - 1) ^ 0x42) & 0xFF
        result.append(chr(original))
    return ''.join(result)

